fn find_user(id: i64) -> Option<String> {
    if id <= 0 {
        None
    } else {
        Some(format!("user-{id}"))
    }
}

struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    fn new() -> Self { Self { items: Vec::new() } }
    fn push(&mut self, value: T) { self.items.push(value); }
    fn pop(&mut self) -> Option<T> { self.items.pop() }
}

use std::collections::HashMap;

fn group_by<T, K, F>(items: Vec<T>, key_fn: F) -> HashMap<K, Vec<T>>
where
    K: Eq + std::hash::Hash,
    F: Fn(&T) -> K,
{
    let mut map = HashMap::new();
    for item in items {
        map.entry(key_fn(&item)).or_default().push(item);
    }
    map
}

async fn fetch_json(url: &str) -> Result<serde_json::Value, reqwest::Error> {
    let response = reqwest::get(url).await?.error_for_status()?;
    response.json().await
}
